const maxDesigns = Number($('Workflow Settings').first().json.maxDesigns) || 100;
const supported = /^image\/(png|jpeg|webp|gif)$/i;
const files = $input.all()
  .map(item => item.json)
  .filter(file => file.id && supported.test(file.mimeType || ''))
  .slice(0, maxDesigns);

if (files.length === 0) {
  throw new Error('No supported image files found. Add PNG, JPEG, WebP or GIF files to the configured Drive folder.');
}

return files.map(file => ({
  json: {
    designName: file.name,
    designFileId: file.id,
    designUrl: `https://drive.google.com/uc?export=download&id=${encodeURIComponent(file.id)}`
  }
}));

const settings = $('Workflow Settings').first().json;
const filter = String(settings.templateNameContains || '').trim().toLowerCase();
const maxTemplates = Number(settings.maxTemplates) || 10;
const templates = $input.all()
  .map(item => item.json)
  .filter(template => {
    const hasSmartObject = Boolean(template.smart_objects?.[0]?.uuid);
    const matchesName = !filter || String(template.name || '').toLowerCase().includes(filter);
    return template.uuid && hasSmartObject && matchesName;
  })
  .slice(0, maxTemplates);

if (templates.length === 0) {
  throw new Error('No matching SudoMock PSD template with a smart object was found.');
}

return templates.map(template => ({
  json: {
    templateName: template.name,
    templateUuid: template.uuid,
    smartObjectUuid: template.smart_objects[0].uuid
  }
}));

const pair = $('Loop through pairs').item.json;
const render = $input.item.json;
const mockupUrl = render.renderedImageUrl || '';
const error = typeof render.error === 'string' ? render.error : render.error?.message || '';

return [{
  json: {
    designName: pair.designName,
    templateName: pair.templateName,
    mockupUrl,
    status: mockupUrl ? 'SUCCESS' : 'FAILED',
    error
  }
}];

const results = $input.all();
if (results.length === 0) throw new Error('No render results were produced.');

return results.map(item => ({
  json: {
    'Design name': item.json.designName,
    'Template name': item.json.templateName,
    'Mockup URL': item.json.mockupUrl,
    Status: item.json.status,
    Error: item.json.error
  }
}));
